function nextDecision(){const o=state.org,p=state.player;if(!state.flags.firstResponse)return{id:"first-response",title:"A student crisis reaches your phone",body:"An old college friend shares painful news from a coaching centre. The student is a fictional composite. How do you respond while you still have work and bills?",choices:[["Post publicly","Visibility brings scrutiny.",{recognition:4,media:2,stress:3,energy:-3}],["Contact a journalist","Seek careful coverage and verification.",{recognition:2,energy:-5,stress:2}],["Help students organise","Build trust at a cost to your job and rest.",{volunteers:5,energy:-9,stress:4}],["Donate quietly","Spend personal savings without publicity.",{energy:1}],["Stay quiet","Protect your job and health for now.",{energy:5,stress:-2}]]};if(state.date>REALITY_CUTOFF){
 if(!state.flags.handoffResolved)return{id:"handoff-eci",title:"The 48-hour ultimatum",body:"On 24 September, the real CJP demanded the Chief Election Commissioner’s resignation and discussed another Jantar Mantar protest. At the historical cutoff, the result was unresolved. You now choose the movement’s next simulated step.",choices:[["Prepare a peaceful gathering","Check permissions, safety, accessibility and volunteers before announcing a date.",{funds:-14000,volunteers:22,credibility:2,media:3,energy:-8}],["Seek documents and an official reply","Ask for records and publish only verified claims.",{funds:-6000,credibility:4,media:1,energy:-6}],["Pause escalation for independent review","Spend time assessing the electoral-roll claims before mobilising.",{funds:-9000,legal:-3,credibility:3,media:-2,energy:-5}]]};

 if(o.funds<o.monthlyBurn)return{title:"The payroll cliff",body:"Your next monthly costs exceed available cash. Staff ask whether you have a credible plan.",choices:[["Launch an emergency donor drive","Disclose the shortfall and ask small donors for help.",{funds:Math.max(12000,Math.round(o.volunteers*35)),credibility:2,stress:4,energy:-8}],["Cut operating costs","Reduce office and travel costs, but slow the campaign.",{volunteers:-12,media:-3,stress:3,energy:-4}],["Hide the problem","Buy time at the cost of trust if people discover it.",{credibility:-5,secret:1,stress:8}]]};
 if(o.legal>45)return{title:"Legal questions reach the office",body:"A complaint about your campaign arrives. The facts require careful review; the legal outcome is not predetermined.",choices:[["Commission an independent review","Spend resources to establish the record.",{funds:-16000,legal:-10,credibility:3,energy:-7}],["Hold a factual briefing","Address verified claims without speculating.",{funds:-5000,legal:-4,media:3,credibility:1}],["Attack the accusers","Rally supporters while increasing exposure.",{support:3,legal:8,credibility:-4,stress:5}]]};
 if(p.stress>68||p.energy<20)return{title:"Your team sees the exhaustion",body:"Late decisions and missed rest are hurting your judgement. Delegation has become a political decision.",choices:[["Delegate the next briefing","Trust a colleague and recover.",{energy:18,stress:-12,media:-2}],["Take a full day away","Protect health while the news cycle moves on.",{energy:26,stress:-18,support:-1}],["Push through","Keep personal control at a human cost.",{support:2,energy:-10,stress:10,health:-3}]]};
 if(state.phase==="government")return{title:"Promises meet the budget",body:"The cabinet can fund visible public services, but the movement treasury cannot substitute for public accounts. Choose a governing priority.",choices:[["Publish a costed service plan","Build confidence before making delivery claims.",{credibility:3,recognition:2,energy:-8}],["Visit under-served districts","Hear complaints firsthand and shift attention locally.",{support:3,energy:-10,stress:2}],["Protect the coalition","Spend time managing relationships.",{support:-1,stress:3,energy:-6}]]};
 if(state.phase==="opposition")return{title:"A constituency wants an answer",body:"Residents bring documents about a delayed public service. The claim is plausible but still needs verification.",choices:[["Send a verification team","Check records before confronting officials.",{funds:-7000,credibility:3,support:1,energy:-5}],["Ask a formal question","Put the concern into the public record.",{media:2,credibility:1,energy:-5}],["Make an immediate accusation","Gain attention while risking an unverified claim.",{media:5,legal:6,credibility:-4}]]};
 }
 return EVENTS[state.eventIndex%EVENTS.length];}
function openDecision(){if(state.lastDecisionDay===state.day)return toast("Today's major decision is complete.");const ev=nextDecision();const modal=document.createElement("div");modal.className="decision-modal";modal.innerHTML=`<div class="decision-box"><small>${state.date>REALITY_CUTOFF?"SIMULATED FUTURE":"FICTIONAL MOVEMENT DECISION"}</small><h2>${safe(ev.title)}</h2><p>${safe(ev.body)}</p><div class="choices">${ev.choices.map((c,i)=>`<button class="choice" data-i="${i}"><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${safe(c[0])}</strong><small>${safe(c[1])}</small></span><span class="choice-effect">CHOOSE</span></button>`).join("")}</div><button class="modal-close" type="button">CLOSE</button></div>`;document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();modal.querySelectorAll(".choice").forEach(b=>b.onclick=()=>{const c=ev.choices[+b.dataset.i],cost=-(c[2].funds||0);if(ev.id==="first-response"&&b.dataset.i==="3"&&state.player.money<2000)return toast("Personal savings are insufficient for that donation.");if(cost>state.org.funds)return toast(`This option needs ₹${money(cost)}.`);applyEffect(c[2]);state.operationProgress=clamp(state.operationProgress+Math.max(5,Math.round(Math.random()*12)));state.lastDecisionDay=state.day;if(ev.id==="handoff-eci")state.flags.handoffResolved=true;if(ev.id==="first-response"){state.flags.firstResponse=c[0];state.player.jobStanding=clamp(state.player.jobStanding+(b.dataset.i==="2"?-8:2));if(b.dataset.i==="3")state.player.money-=2000;}record(ev.title,c[0]);state.eventIndex++;advanceDay();modal.remove();toast(c[0]+" — consequences recorded.");});}
function simulateElection(){const seed=(state.electionSeed+state.day*7919+state.elections.length*104729)>>>0;let value=seed;const random=()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296;};const byState={};let seats=0,weightedStrength=0;for(const [name,count] of Object.entries(SEAT_COUNTS)){const local=state.org.presence[name]||0;const strength=Math.max(1,Math.min(65,state.general*.35+state.support*.15+state.campaign.preparation*.08+state.org.credibility*.04+Math.min(10,state.org.volunteers/300)+local*.22-state.org.legal*.1));let won=0;for(let i=0;i<count;i++){const noise=(random()-.5)*30,threshold=25+(random()-.5)*16;if(strength+noise>threshold)won++;}byState[name]={won,total:count,strength:Math.round(strength*10)/10};seats+=won;weightedStrength+=strength*count;}return{date:state.date,seats,voteShare:Math.round(weightedStrength/543*10)/10,result:seats>=272?"Government":seats>0?"Opposition":"No seats",byState};}
function applyEffect(e){if(!state.player)return;const p=state.player,o=state.org;Object.entries(e).forEach(([k,v])=>{if(k==="support")state.support=clamp(state.support+v);else if(k==="general")state.general=clamp(state.general+v);else if(k==="followers")state.followers=Math.max(0,state.followers+v);else if(k==="funds")o.funds=Math.max(0,o.funds+v);else if(k==="volunteers")o.volunteers=Math.max(0,o.volunteers+v);else if(k==="staff")o.staff=Math.max(0,o.staff+v);else if(k==="credibility")o.credibility=clamp(o.credibility+v);else if(k==="media")o.media=clamp(o.media+v);else if(k==="legal")o.legal=clamp(o.legal+v);else if(k==="secret")state.secrets=(state.secrets||0)+v;else if(k in p)p[k]=k==="money"?Math.max(0,p[k]+v):clamp(p[k]+v)});}
function advanceDay(){ensureState();state.day++;const d=new Date(state.date+"T00:00:00Z");d.setUTCDate(d.getUTCDate()+1);state.date=d.toISOString().slice(0,10);for(const scene of REAL_SCENES){if(!scene.archive&&scene.date===state.date&&!state.sceneResponses[scene.id]&&!state.pendingScenes.includes(scene.id)){state.pendingScenes.push(scene.id);record("Historical dispatch",scene.title);}}state.player.energy=clamp(state.player.energy-3);state.player.stress=clamp(state.player.stress+1+(state.player.energy<30?2:0));if(state.org.volunteers>0)state.followers+=Math.round(state.org.media*2+state.org.volunteers*.3);state.player.level=1+Math.floor((state.day-1)/7);for(const x of state.projects.filter(v=>v.status==="active")){x.remaining--;if(x.remaining<=0){x.status="completed";applyEffect(x.effect);record("Operation completed",`${x.name} produced measurable results.`);}}if(state.day%30===0){state.player.money=Math.max(0,state.player.money+Math.round((state.player.monthlyIncome??35000)*(state.player.jobStanding??75)/100)-(state.player.monthlyLivingCosts??22000));const due=state.org.monthlyBurn,paid=Math.min(due,state.org.funds);state.org.funds-=paid;if(paid<due){state.org.credibility=clamp(state.org.credibility-4);state.player.stress=clamp(state.player.stress+8);record("Payroll shortfall",`Only ₹${money(paid)} of ₹${money(due)} in monthly costs could be paid.`);}else record("Monthly costs paid",`₹${money(due)} covered salaries, travel and tools.`);}if(state.date==="2026-07-25"&&!state.flags.reportedResignation){state.flags.reportedResignation=true;record("Historical anchor","The Education Minister resignation is reported. Your campaign trust and negotiating position remain consequences of your own decisions.");}if(state.player.energy<12){state.player.health=clamp(state.player.health-1);state.player.stress=clamp(state.player.stress+2);}save();renderGame();}
function updateDate(){const d=new Date(state.date+"T00:00:00Z");$("#date-label").textContent=new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"}).format(d).toUpperCase();$("#ticker-text").textContent=`${state.player.name}'s movement enters Day ${state.day} · Volunteers ${state.org.volunteers.toLocaleString("en-IN")} · Credibility ${state.org.credibility}/100 · Media heat ${state.org.media}/100`;}
function money(n){return n>=10000000?(n/10000000).toFixed(2)+" Cr":n>=100000?(n/100000).toFixed(1)+" L":n.toLocaleString("en-IN")}
function fmtFollowers(){return state.followers>=1000000?(state.followers/1000000).toFixed(1)+"M":state.followers>=1000?(state.followers/1000).toFixed(1)+"K":state.followers}
function save(){localStorage.setItem("republic543-save",JSON.stringify(state));}
let toastTimer;function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2400)}
